FILES = {'vram_peak.py': ('92f44120afb3747dc22fa5bce048ede6c50690b064afc1aeeb18125ce58879d5', '"""版107e：その回の GPU 全体の最大使用（ドライバの値。ほかのプログラム・画面の分も入る）を測って、終わりに出して残す\n  【み】11-05 07:30「ハード側でAnaPlex全体のその回での最大使用量がわかるようにしておいて」\n  網を組むとき（Brain の __init__）に start() ⇒ 裏で 1秒ごとに torch.cuda.mem_get_info（ドライバ）を見る\n    ⟲ 20ms ごと（版107e の初め）は、見ること自体が網の歩とドライバ・Python を取り合う【み】11-05 12:17 ⇒ 1秒\n  1秒の間の短い山は、PyTorch が自分で数えている取り置きの山（max_memory_reserved、数えるのに手間なし・取りこぼしなし）で拾う\n    GPU 全体の山の下限 ＝ max（1秒ごとに見た山, 取り置きの山 ＋ PyTorch の外の一番小さい値）\n    ⟲ 外の一番大きい値を足した形（11-05）は、外と取り置きの山が別の時刻なので 18.51GB のような見込みすぎが出た\n  終わり（プログラムを閉じるとき）に 1行出し、logs/vram_peak.log に 1行足す\n"""\nimport atexit, datetime, os, sys, threading, time\n\n_state = {"on": False}\n\n\ndef start(dev_index=0, every_s=1.0):\n    """何度呼んでも 1回だけ始める（GPU が無ければ何もしない）"""\n    if _state["on"]:\n        return\n    import torch\n    if not torch.cuda.is_available():\n        return\n    _state.update(on=True, peak=0.0, t_peak=0.0, t0=time.time(), first=None, total=0.0, n=0, stop=False, outside=0.0, out_min=None)\n\n    def _look():\n        free, total = torch.cuda.mem_get_info(dev_index)\n        used = (total - free) / 1024 ** 3\n        _state["total"] = total / 1024 ** 3\n        if _state["first"] is None:\n            _state["first"] = used\n        if used > _state["peak"]:\n            _state["peak"], _state["t_peak"] = used, time.time() - _state["t0"]\n        rs_ = torch.cuda.memory_reserved(dev_index) / 1024 ** 3\n        _state["outside"] = max(_state["outside"], used - rs_)\n        if rs_ > 0:\n            _state["out_min"] = used - rs_ if _state["out_min"] is None else min(_state["out_min"], used - rs_)\n        _state["n"] += 1\n\n    def _loop():\n        torch.cuda.set_device(dev_index)\n        while not _state["stop"]:\n            try:\n                _look()\n            except Exception:\n                pass\n            time.sleep(every_s)\n\n    _look()\n    threading.Thread(target=_loop, daemon=True, name="vram_peak").start()\n    atexit.register(_report)\n\n\ndef peak():\n    """今までの山（GB）"""\n    return _state.get("peak", 0.0)\n\n\ndef _report():\n    if not _state["on"]:\n        return\n    _state["stop"] = True\n    try:\n        import torch\n        free, total = torch.cuda.mem_get_info()\n        used = (total - free) / 1024 ** 3\n        if used > _state["peak"]:\n            _state["peak"], _state["t_peak"] = used, time.time() - _state["t0"]\n    except Exception:\n        pass\n    try:\n        import torch\n        rpk = torch.cuda.max_memory_reserved() / 1024 ** 3\n    except Exception:\n        rpk = 0.0\n    omin = _state["out_min"] or 0.0\n    est = max(_state["peak"], rpk + omin)\n    tool = os.path.basename(sys.argv[0]) if sys.argv and sys.argv[0] else "?"\n    line = (f"{datetime.datetime.now():%Y-%m-%d %H:%M:%S} {tool} {\' \'.join(sys.argv[1:])} ／ GPU 全体の山 {_state[\'peak\']:.2f}GB"\n            f"（1秒ごと・始めから {_state[\'t_peak\']:.0f}秒）／ 山の下限 {est:.2f}GB（取り置きの山 {rpk:.2f} ＋ 外の一番小さい値 {omin:.2f}）／ 始めの使用 {(_state[\'first\'] or 0):.2f}GB ／ 全体 {_state[\'total\']:.2f}GB")\n    print(f"［VRAM］この回の GPU 全体の山は少なくとも {est:.2f}GB（PyTorch の取り置きの山 {rpk:.2f} ＋ 外の一番小さい値 {omin:.2f}）"\n          f"・1秒ごとに見た山 {_state[\'peak\']:.2f}GB（始めから {_state[\'t_peak\']:.0f}秒）・網を組む前 "\n          f"{(_state[\'first\'] or 0):.2f}GB・全体 {_state[\'total\']:.2f}GB）⇒ logs/vram_peak.log", flush=True)\n    try:\n        os.makedirs("logs", exist_ok=True)\n        with open(os.path.join("logs", "vram_peak.log"), "a") as f:\n            f.write(line + "\\n")\n    except Exception:\n        pass\n'), 'measure_quiet107.py': (None, '"""版107e：50番で網が静かになる元を分ける（arkhe の ~/anaplex で。保存しない・網は変えない）\n  python3 measure_quiet107.py [番=50] [何番ごとに見る=5]\n  knobs.json があればそれで（版107e）。5番ごとに 1行：歩・起きている／眠り・門（黒質・VTA）・皮質の表現の率・\n    恒常性の下げ（scale、眠りで下げる）と上げ（scale_up、起きていて上げる）の皮質・核・線条体の平均・生きている辺の数・辺の重さの平均\n  終わりに領野ごとの 0番 → 終わりの比（scale・scale_up・入る辺の重さの和・辺の数）\n"""\nimport os, sys, numpy as np, torch\nos.environ.setdefault("ANAPLEX_GRAPH", "eager")\nimport babble as B, brainstem as BS, torch_area as T\nimport torch_brain as TB\nfrom torch_brain import Brain, NAMES\n\nargs = [a for a in sys.argv[1:] if not a.startswith("--")]\nNP = int(args[0]) if args else 50\nEV = int(args[1]) if len(args) > 1 else 5\nTEST = "--test" in sys.argv\nif TEST:\n    B.DEV = "cpu"\ndev = B.DEV\ntorch.manual_seed(0)\nb = Brain(T.Prior.load("prior_v1.npz", dev=dev), n_partner=(200 if TEST else 9100), hippo_scale=20.0, n_ear=B.N_EAR, dev=dev)\nb.bs.set_state(BS.WAKE)\nlife = B.life_of(b, True, np.random.default_rng(0), np.random.default_rng(1))\ng = b.g\nCX = [nm for nm in NAMES if TB.PRIOR_TYPE.get(nm) == "皮質"]\nNUCS = list(TB.NUC)\nSTRS = ["尾状核", "被殻", "側坐核", "ストリオソーム"]\n\n\ndef rows(nms):\n    idx = []\n    for nm in nms:\n        i = NAMES.index(nm)\n        idx.append(torch.arange(int(g.off_recv[i]), int(g.off_recv[i + 1]), device=dev))\n    return torch.cat(idx)\n\n\nR = {"皮質": rows(CX), "核": rows(NUCS), "線条体": rows(STRS)}\n\n\ndef per_area():\n    g.flush_all()\n    live = g.w > 0\n    wsum = torch.zeros(g.n_recv_all, device=dev).index_add_(0, g.e_recv.long(), g.w.float())\n    ecnt = torch.zeros(g.n_recv_all, device=dev).index_add_(0, g.e_recv.long(), live.float())\n    out = {}\n    for i, nm in enumerate(NAMES):\n        lo, hi = int(g.off_recv[i]), int(g.off_recv[i + 1])\n        out[nm] = (float(g.scale[lo:hi].mean()), float(g.scale_up[lo:hi].mean()), float(wsum[lo:hi].sum()), float(ecnt[lo:hi].sum()))\n    return out\n\n\ndef rate_cx(steps=20):\n    acc = torch.zeros(g.n_ch_all, device=dev, dtype=torch.float64)\n    for _ in range(steps):\n        life.step()\n        acc += g._any[0][:g.n_ch_all].double()\n    rs = []\n    for nm in TB.X_CX_AREAS:\n        i = NAMES.index(nm)\n        o, n = int(b.off_ch[i]), b.n[nm]\n        rs.append(float(acc[o:o + n].mean()) / steps / 0.01067)\n    return float(np.mean(rs))\n\n\np0 = per_area()\nprint("番 ・ 歩 ・ 状態 ・ 門（黒質・VTA）・ 皮質の率 ・ scale（皮質・核・線条体）・ scale_up（皮質・核・線条体）・ 生きている辺 ・ 辺の重さの平均", flush=True)\ndone = 0\nwhile True:\n    rc = rate_cx()\n    g.flush_all()\n    live = g.w > 0\n    st = "眠り" if getattr(g, "sleep_mode", False) else "起き"\n    sc = "・".join(f"{float(g.scale[r].mean()):.3f}" for r in R.values())\n    su = "・".join(f"{float(g.scale_up[r].mean()):.3f}" for r in R.values())\n    print(f"{done:3d}番 {life.t:6d}歩 {st} 門 {float(b.gate[0]):.2f}・{float(b.gate[1]):.2f} 皮質 {rc:5.2f}Hz scale {sc} scale_up {su} "\n          f"辺 {int(live.sum()):,} 重さ {float(g.w[live].mean()):.4f}", flush=True)\n    if done >= NP:\n        break\n    life.run_plans(EV, learn=True)\n    done += EV\np1 = per_area()\nprint("\\n領野ごと 0番 → 終わり（比）：scale ・ scale_up ・ 入る辺の重さの和 ・ 辺の数", flush=True)\nfor nm in NAMES:\n    a, c = p0[nm], p1[nm]\n    r_ = lambda x, y: (y / x) if x else float("nan")\n    print(f"  {nm:<8s} {r_(a[0], c[0]):6.3f} {r_(a[1], c[1]):7.3f} {r_(a[2], c[2]):7.3f} {r_(a[3], c[3]):7.3f}", flush=True)\n')}

import ast, hashlib, pathlib, sys

bad = []
for f, (h, text) in FILES.items():
    ast.parse(text)
    p = pathlib.Path(f)
    if p.exists() and p.read_text() == text:
        continue
    if h is None:                      # 新しく置くファイル（あれば止まる）
        if p.exists():
            bad.append(f)
        continue
    if not p.exists() or hashlib.sha256(p.read_bytes()).hexdigest() != h:
        bad.append(f)
if bad:
    sys.exit(f"⚠️ {bad} が思っていた形ではない（手で直した所があるか、版が違う）。何も書き換えていない")
for f, (_, text) in FILES.items():
    pathlib.Path(f).write_text(text)
print("✅ 版107f を当てた", flush=True)
